/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ielts_test_questions` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `section_id` int unsigned NOT NULL,
  `part_id` bigint unsigned DEFAULT NULL,
  `question_group_id` bigint unsigned DEFAULT NULL,
  `question_number` int NOT NULL COMMENT 'Global number 1-40',
  `question_order` int NOT NULL DEFAULT '0',
  `question_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `question_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `question_audio` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instruction` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g., Write NO MORE THAN TWO WORDS',
  `correct_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'JSON array for multiple answers',
  `table_structure` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `flow_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `question_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `answer_options` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'JSON array for MC options',
  `accept_synonyms` tinyint(1) DEFAULT '0',
  `case_sensitive` tinyint(1) DEFAULT '0',
  `max_words` int DEFAULT NULL COMMENT 'For fill-in-blank',
  `max_selections` int DEFAULT NULL COMMENT 'For multiple_select',
  `min_words_essay` int DEFAULT NULL COMMENT 'For Writing essays',
  `points` decimal(3,1) DEFAULT '1.0',
  `auto_gradable` tinyint(1) DEFAULT '1' COMMENT '0 for Writing/Speaking',
  `hint` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `audio_timestamp` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g., 02:15',
  `common_mistakes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `sort_order` int NOT NULL,
  `created_at` bigint unsigned NOT NULL,
  `source_question_id` int unsigned DEFAULT NULL,
  `source_bank_type` enum('mock','practice') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `word_limit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_section_question` (`section_id`,`question_number`),
  KEY `idx_question_number` (`question_number`),
  KEY `idx_question_type` (`question_type`),
  KEY `idx_source` (`source_bank_type`,`source_question_id`),
  KEY `ielts_test_questions_question_group_id_index` (`question_group_id`),
  KEY `ielts_test_questions_part_id_index` (`part_id`),
  CONSTRAINT `fk_question_section` FOREIGN KEY (`section_id`) REFERENCES `ielts_test_sections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ielts_test_questions_part_id_foreign` FOREIGN KEY (`part_id`) REFERENCES `ielts_test_parts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ielts_test_questions_chk_1` CHECK (json_valid(`table_structure`)),
  CONSTRAINT `ielts_test_questions_chk_2` CHECK (json_valid(`flow_data`)),
  CONSTRAINT `ielts_test_questions_chk_3` CHECK (json_valid(`question_data`))
) ENGINE=InnoDB AUTO_INCREMENT=15977 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
