--
-- Table structure for table `ielts_question_groups`
--

DROP TABLE IF EXISTS `ielts_question_groups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ielts_question_groups` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `section_id` bigint unsigned DEFAULT NULL,
  `part_id` bigint unsigned DEFAULT NULL,
  `creator_id` int unsigned NOT NULL,
  `bank_type` enum('mock','practice') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `skill` enum('listening','reading','writing','speaking') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `question_start` int DEFAULT NULL,
  `question_end` int DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g., "Climate Change Passage", "Part 1 Audio"',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `instructions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `max_words` int DEFAULT NULL,
  `passage` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Reading passage with rich text',
  `transcript` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Listening transcript',
  `audio_file` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path to audio file',
  `video_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audio_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `task_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Writing task chart/diagram',
  `target_band` decimal(2,1) DEFAULT NULL COMMENT 'For practice questions',
  `practice_focus` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT 'Topics: ["environment", "technology"]',
  `difficulty_level` enum('beginner','intermediate','advanced') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `usage_count` int unsigned DEFAULT '0' COMMENT 'Times used in tests',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `audio_duration` int DEFAULT NULL COMMENT 'Seconds',
  `question_count` tinyint DEFAULT '0',
  `topic` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('draft','pending','approved','rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'draft',
  `submitted_by` int unsigned DEFAULT NULL,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `approved_by` int unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejection_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_bank_skill` (`bank_type`,`skill`),
  KEY `idx_creator` (`creator_id`),
  KEY `idx_difficulty` (`difficulty_level`),
  KEY `idx_deleted` (`deleted_at`),
  KEY `idx_status` (`status`),
  KEY `idx_topic` (`topic`),
  KEY `ielts_question_groups_part_id_index` (`part_id`),
  CONSTRAINT `ielts_question_groups_ibfk_1` FOREIGN KEY (`creator_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ielts_question_groups_part_id_foreign` FOREIGN KEY (`part_id`) REFERENCES `ielts_test_parts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ielts_question_groups_chk_1` CHECK (json_valid(`tags`))
) ENGINE=InnoDB AUTO_INCREMENT=6916 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ielts_question_groups`
--

LOCK TABLES `ielts_question_groups` WRITE;
/*!40000 ALTER TABLE `ielts_question_groups` DISABLE KEYS */;
INSERT INTO `ielts_question_groups` VALUES (1,NULL,NULL,1049,'mock','reading',NULL,NULL,NULL,'MOCK TEST 01',NULL,NULL,NULL,'<h3 style=\"margin-top: 0.6em; margin-bottom: 0.5em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-weight: inherit; font-stretch: inherit; font-size: 1.25em; line-height: 1.3; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\"><span style=\"margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline;\">The Enigma of Sleep – Decoding Our Nocturnal Lives</span></h3><p>Sleep is a fundamental human need, as vital to our health as eating, drinking, and breathing. It’s a complex, dynamic state rather than a passive one. For centuries, the exact purpose and mechanisms of sleep remained largely a mystery. However, advancements in neuroscience and sleep research over the past few decades have shed considerable light on this enigmatic process, revealing its profound impact on our physical and mental well-being.</p><p><br></p><p>Scientists typically divide sleep into two basic types: Rapid Eye Movement (REM) sleep and non-Rapid Eye Movement (NREM) sleep. NREM sleep is further categorized into three stages, each progressively deeper. Stage 1 NREM is a light sleep, a transition from wakefulness. Stage 2 NREM is characterized by a slower heart rate and a drop in body temperature. Stage 3 NREM, often referred to as “deep sleep” or “slow-wave sleep,” is the most restorative stage, crucial for physical recovery and growth. During this stage, brain waves slow significantly, and it’s hardest to awaken someone.</p><p><br></p><p>REM sleep, on the other hand, is the stage where most dreaming occurs. Despite the body being largely paralyzed (a protective mechanism to prevent us from acting out our dreams), brain activity during REM sleep is remarkably similar to that of wakefulness. This stage is particularly important for cognitive functions, including memory consolidation, learning, and emotional processing. A typical night’s sleep involves cycling through these NREM and REM stages multiple times, with each cycle lasting approximately 90-110 minutes. Early in the night, NREM deep sleep dominates, while REM sleep periods become longer towards morning.</p><p><br></p><p>The benefits of adequate sleep are vast and multifaceted. Physically, sleep allows the body to repair and regenerate, strengthening the immune system and regulating hormones essential for appetite and metabolism. Mentally, it clears the mind, enhances problem-solving skills, and improves concentration and mood. Chronic sleep deprivation, conversely, has detrimental effects, ranging from impaired cognitive function and reduced productivity to an increased risk of serious health conditions like obesity, diabetes, and cardiovascular disease. Understanding these intricate processes is key to appreciating sleep not as a luxury, but as an indispensable pillar of a healthy life.</p>',NULL,NULL,NULL,NULL,NULL,5.0,NULL,NULL,'beginner',0,'2026-01-04 19:50:11','2026-01-04 19:50:11',NULL,NULL,0,NULL,'draft',NULL,NULL,NULL,NULL,NULL),(2,NULL,NULL,1049,'practice','reading',NULL,NULL,NULL,'PRACTICE TEST DEMO 01',NULL,NULL,NULL,'<p><b>The Ubiquitous and Indispensable Kingdom</b><br>Fungi, often overlooked or simply associated with mushrooms on pizza, represent an extraordinarily diverse and vital kingdom of life. Neither plant nor animal, they occupy their own unique evolutionary branch, boasting an estimated 2.2 to 3.8 million species, only about 120,000 of which have been formally described. From the microscopic yeasts that ferment our bread and beer to the vast networks of mycelium sprawling beneath forest floors, fungi play an indispensable role in nearly every ecosystem on Earth.</p><p>Their ecological significance stems primarily from their role as decomposers. Unlike plants, which produce their own food through photosynthesis, or animals, which ingest food, fungi secrete powerful enzymes into their environment. These enzymes break down complex organic matter – dead plants, animals, and waste products – into simpler substances, which the fungi then absorb. This process is crucial for recycling nutrients, making them available for other organisms, and thus maintaining the fertility of soils worldwide. Without fungi, the Earth would be buried under mountains of undecomposed organic debris.</p><p>Beyond decomposition, fungi form a myriad of fascinating symbiotic relationships. The most widespread are mycorrhizal associations, where fungi live in close proximity to plant roots. In this mutually beneficial partnership, the fungus extends its hyphae (root-like structures) far into the soil, vastly increasing the plant’s access to water and essential nutrients like phosphorus and nitrogen. In return, the plant provides the fungus with carbohydrates produced during photosynthesis. This relationship is so vital that an estimated 90% of all plant species, including most crops, rely on mycorrhizal fungi for optimal growth.</p><p>Lichens, another remarkable symbiotic entity, are a partnership between a fungus and an alga (or cyanobacterium). Here, the fungus provides a protective structure, moisture, and minerals, while the alga performs photosynthesis, supplying food for both. Lichens are incredible pioneers, capable of colonizing harsh environments like bare rock, where they slowly contribute to soil formation.</p><p>The economic and medical importance of fungi is equally profound. Yeasts are fundamental to baking and brewing industries. Penicillin, the first widely used antibiotic, was discovered from the fungus Penicillium chrysogenum, revolutionizing medicine. Fungi are also increasingly used in bioremediation, helping clean up oil spills and other pollutants. Despite their immense contributions, many fungal species remain a mystery, underscoring the vast potential yet to be uncovered in this silent, powerful kingdom.</p>',NULL,NULL,NULL,NULL,NULL,5.0,NULL,NULL,'beginner',0,'2026-01-04 20:20:24','2026-01-06 01:13:13','2026-01-06 01:13:13',NULL,0,NULL,'draft',NULL,NULL,NULL,NULL,NULL),(3,NULL,NULL,1049,'practice','reading',NULL,NULL,NULL,'Readinh test practice',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,5.5,NULL,NULL,'beginner',0,'2026-01-04 21:13:38','2026-01-05 00:14:49','2026-01-05 00:14:49',NULL,0,NULL,'draft',NULL,NULL,NULL,NULL,NULL),(4,NULL,NULL,1049,'practice','reading',NULL,NULL,NULL,'Readinh test practice',NULL,'The Challenge of Sustainable Urban Development – Building Cities for the Future',NULL,'<p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\"><span style=\"margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline;\">Balancing Growth with Environmental Responsibility</span></p><p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\">As the global population continues to urbanize at an unprecedented rate, cities face immense pressure to accommodate growth while simultaneously addressing pressing environmental and social challenges.&nbsp;<span style=\"margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline;\">Sustainable urban development</span>&nbsp;has emerged as a critical paradigm, aiming to create cities that are not only economically vibrant and socially equitable but also environmentally benign and resilient. This approach involves a complex interplay of planning, policy, and technological innovation, striving for a balance that can meet the needs of the present without compromising the ability of future generations to meet their own needs.</p><p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\">One key pillar of sustainable urban development is&nbsp;<span style=\"margin: 0px; padding: 0px; border: 0px; font-style: inherit; font-variant: inherit; font-weight: 700; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline;\">resource efficiency</span>. This encompasses strategies for reducing energy consumption through smart building designs, promoting renewable energy sources, and optimizing water usage through greywater recycling and rainwater harvesting. Waste management is another crucial aspect, with an emphasis on reducing, reusing, and recycling, moving towards a circular economy model where waste is seen as a resource. Efficient public transportation systems are also vital to reduce reliance on private vehicles, thereby cutting down on greenhouse gas emissions and improving air quality.</p><p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\">Beyond environmental concerns, social equity plays an equally significant role. A truly sustainable city fosters inclusivity, ensuring access to affordable housing, quality education, healthcare, and green spaces for all residents, regardless of their socioeconomic status. Community participation in planning processes is encouraged to ensure that developments truly reflect the needs and aspirations of the local population. This focus on human well-centric design creates healthier, more livable urban environments.</p><p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\">However, implementing sustainable urban development faces significant hurdles. Rapid urbanization in developing countries often outpaces planning capabilities, leading to informal settlements and inadequate infrastructure. In developed nations, existing infrastructure can be difficult and costly to retrofit. The initial investment required for green technologies and sustainable infrastructure can also be substantial, posing financial barriers. Moreover, achieving consensus among diverse stakeholders – governments, businesses, and communities – on long-term visions and immediate actions remains a continuous challenge.</p><p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\">Despite these obstacles, the imperative for sustainable urban development is undeniable. Cities are powerful engines of economic growth and innovation, and by transforming them into models of sustainability, they can become laboratories for solutions to global challenges. Collaborative efforts, technological breakthroughs, and a collective commitment to long-term well-being will be essential in shaping the cities of tomorrow – places where prosperity and ecological balance can truly coexis</p>',NULL,NULL,NULL,NULL,NULL,5.5,NULL,NULL,'beginner',4,'2026-01-04 21:14:56','2026-01-10 04:35:10',NULL,NULL,0,NULL,'approved',NULL,NULL,NULL,NULL,NULL),(5,NULL,NULL,1049,'practice','reading',NULL,NULL,NULL,'Reading - Architects',NULL,'The Silent Architects – How Fungi Shape Our World',NULL,'<p style=\"margin-top: 1em; margin-bottom: 1em; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 16px; line-height: inherit; font-family: &quot;Plus Jakarta Sans&quot;; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; vertical-align: baseline; color: rgb(89, 89, 89);\"><span style=\"margin: 0px; padding: 0px; border: 0px; font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-weight: 700; font-stretch: inherit; line-height: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-varia